beforeSaveCustomScript:
name = feedbackFormID; // replace Espo autogenerated random sequence for a more logical case ID


// -------------------------
// Helpers (pattern repeated)
// -------------------------
// Rule: if Kobo sends '' for an unanswered datetime question, NEVER write '' to a MySQL DATETIME column.
// Set the converted datetime field to null instead, otherwise you get:
// SQLSTATE[22007] Incorrect datetime value: ''


// convert dateTimeKoboStartedRaw to dateTimeKoboStarted
$src = dateTimeKoboStartedRaw;
if ($src == null || $src == '') {
  dateTimeKoboStarted = null;
} else {
  $len = string\length($src);
  $raw = string\replace(string\substring($src, 0, 19), 'T', ' ');
  $out = $raw;

  // if timezone offset exists like +05:30 or -03:00, convert to UTC by shifting minutes
  if ($len > 24) {
    $sign = string\substring($src, $len - 6, 1);
    $oh   = string\substring($src, $len - 5, 2) * 1;
    $om   = string\substring($src, $len - 2, 2) * 1;

    $offset = $oh * 60 + $om;
    if ($sign == '+') { $offset = -$offset; }

    $out = datetime\addMinutes($raw, $offset);
  }

  dateTimeKoboStarted = $out;
}


// convert dateTimeKoboCompletedRaw to dateTimeKoboCompleted
$src = dateTimeKoboCompletedRaw;
if ($src == null || $src == '') {
  dateTimeKoboCompleted = null;
} else {
  $len = string\length($src);
  $raw = string\replace(string\substring($src, 0, 19), 'T', ' ');
  $out = $raw;

  if ($len > 24) {
    $sign = string\substring($src, $len - 6, 1);
    $oh   = string\substring($src, $len - 5, 2) * 1;
    $om   = string\substring($src, $len - 2, 2) * 1;

    $offset = $oh * 60 + $om;
    if ($sign == '+') { $offset = -$offset; }

    $out = datetime\addMinutes($raw, $offset);
  }
  dateTimeKoboCompleted = $out;
}


// convert dateTimeKoboSubmittedRaw to dateTimeKoboSubmitted
$src = dateTimeKoboSubmittedRaw;
if ($src == null || $src == '') {
  dateTimeKoboSubmitted = null;
} else {
  $len = string\length($src);
  $raw = string\replace(string\substring($src, 0, 19), 'T', ' ');
  $out = $raw;

  if ($len > 24) {
    $sign = string\substring($src, $len - 6, 1);
    $oh   = string\substring($src, $len - 5, 2) * 1;
    $om   = string\substring($src, $len - 2, 2) * 1;
    $offset = $oh * 60 + $om;
    if ($sign == '+') { $offset = -$offset; }
    $out = datetime\addMinutes($raw, $offset);
  }
  dateTimeKoboSubmitted = $out;
}

// calculate duration of completion of Kobo form in minutes
if (dateTimeKoboCompleted == null || dateTimeKoboStarted == null) {
  durationKoboCompletion = null;
} else {
  durationKoboCompletion = datetime\diff(dateTimeKoboCompleted, dateTimeKoboStarted, 'minutes');
}

// convert dateTimeEventOccurredRaw to dateTimeEventOccurred
$src = dateTimeEventOccurredRaw;
if ($src == null || $src == '') {
  dateTimeEventOccurred = null;
} else {
  $len = string\length($src);
  $raw = string\replace(string\substring($src, 0, 19), 'T', ' ');
  $out = $raw;

  if ($len > 24) {
    $sign = string\substring($src, $len - 6, 1);
    $oh   = string\substring($src, $len - 5, 2) * 1;
    $om   = string\substring($src, $len - 2, 2) * 1;

    $offset = $oh * 60 + $om;
    if ($sign == '+') { $offset = -$offset; }

    $out = datetime\addMinutes($raw, $offset);
  }
  dateTimeEventOccurred = $out;
}


// convert dateTimePaperRecordedRaw to dateTimePaperRecorded
$src = dateTimePaperRecordedRaw;
if ($src == null || $src == '') {
  dateTimePaperRecorded = null;
} else {
  $len = string\length($src);
  $raw = string\replace(string\substring($src, 0, 19), 'T', ' ');
  $out = $raw;

  if ($len > 24) {
    $sign = string\substring($src, $len - 6, 1);
    $oh   = string\substring($src, $len - 5, 2) * 1;
    $om   = string\substring($src, $len - 2, 2) * 1;
    $offset = $oh * 60 + $om;
    if ($sign == '+') { $offset = -$offset; }
    $out = datetime\addMinutes($raw, $offset);
  }

  dateTimePaperRecorded = $out;
}


// set dateTimeFollowUpNeeded when follow up is needed
// when Follow‑up needed is changed to “yes” on an existing record and the timestamp is still empty,
// dateTimeFollowUpNeeded is set to the current date and time.
if (followUpNeeded == 'yes' && dateTimeFollowUpNeeded == null) {
  if (entity\isNew()) {
    dateTimeFollowUpNeeded = createdAt; // could later include dateTimeKoboCompleted/dateTimePaperRecorded if desired
  } else if (entity\isAttributeChanged('followUpNeeded')) {
    dateTimeFollowUpNeeded = datetime\now();
  }
};


// set dateTimeAssigned when user is assigned
if (assignedUserId != null && dateTimeAssigned == null) {
  if (entity\isNew()) {
    dateTimeAssigned = createdAt;
  } else if (entity\isAttributeChanged('assignedUserId')) {
    dateTimeAssigned = datetime\now();
  }
};


// set dateTimeClosed when status is closed
if (status == 'closed' && dateTimeClosed == null) {
  if (entity\isNew()) {
    dateTimeClosed = createdAt;
  } else if (entity\isAttributeChanged('status')) {
    dateTimeClosed = datetime\now();
  }
};


// durationPaperToDigital: hours between paper recorded and record creation
if (createdAt == null || dateTimePaperRecorded == null) {
  durationPaperToDigital = null;
} else {
  durationPaperToDigital = datetime\diff(createdAt, dateTimePaperRecorded, 'minutes') / 60;
};


// durationKoboToDigital: hours between finishing Kobo form and record creation
if (createdAt == null || dateTimeKoboCompleted == null) {
  durationKoboToDigital = null;
} else {
  durationKoboToDigital = datetime\diff(createdAt, dateTimeKoboCompleted, 'minutes') / 60;
};


// durationToAssignment: hours from record creation to first assignment
if (dateTimeAssigned == null || createdAt == null) {
  durationToAssignment = null;
} else {
  durationToAssignment = datetime\diff(dateTimeAssigned, createdAt, 'minutes') / 60;
};


// durationAssignmentToClosure: hours from assignment to closure
if (dateTimeClosed == null || dateTimeAssigned == null) {
  durationAssignmentToClosure = null;
} else {
  durationAssignmentToClosure = datetime\diff(dateTimeClosed, dateTimeAssigned, 'minutes') / 60;
};


// durationToFollowUp: hours from record creation to first follow-up decision
if (createdAt == null || dateTimeFollowUpNeeded == null) {
  durationToFollowUp = null;
} else {
  durationToFollowUp = datetime\diff(dateTimeFollowUpNeeded, createdAt, 'minutes') / 60;
};


// durationEventToReporting: hours from event occurred to first reporting moment (paper recorded OR kobo started)
if (dateTimeEventOccurred == null || (dateTimePaperRecorded == null && dateTimeKoboStarted == null)) {
  durationEventToReporting = null;
} else {
  $reportedAt = null;

  // select earliest of dateTimePaperRecorded and dateTimeKoboStarted
  if (dateTimePaperRecorded != null && dateTimeKoboStarted != null) {
    if (datetime\diff(dateTimePaperRecorded, dateTimeKoboStarted, 'seconds') <= 0) {
      $reportedAt = dateTimePaperRecorded;
    } else {
      $reportedAt = dateTimeKoboStarted;
    }
  } else {
    $reportedAt = dateTimePaperRecorded ?? dateTimeKoboStarted;
  }

  if ($reportedAt == null) {
    durationEventToReporting = null;
  } else {
    durationEventToReporting = datetime\diff($reportedAt, dateTimeEventOccurred, 'minutes') / 60;
  }
};


// durationCommunityToAssignment: Community → assignment (total delay before action), hours
if (durationEventToReporting == null || durationToAssignment == null) {
  durationCommunityToAssignment = null;
} else if (durationKoboToDigital != null) {
  durationCommunityToAssignment = durationEventToReporting + durationKoboToDigital + durationToAssignment;
} else if (durationPaperToDigital != null) {
  durationCommunityToAssignment = durationEventToReporting + durationPaperToDigital + durationToAssignment;
} else {
  durationCommunityToAssignment = null;
};


// durationCommunityToClosureDecomposed: Community → closure (decomposed), hours
if (durationEventToReporting == null || durationToAssignment == null || durationAssignmentToClosure == null) {
  durationCommunityToClosureDecomposed = null;
} else if (durationKoboToDigital != null) {
  durationCommunityToClosureDecomposed =
    durationEventToReporting + durationKoboToDigital + durationToAssignment + durationAssignmentToClosure;
} else if (durationPaperToDigital != null) {
  durationCommunityToClosureDecomposed =
    durationEventToReporting + durationPaperToDigital + durationToAssignment + durationAssignmentToClosure;
} else {
  durationCommunityToClosureDecomposed = null;
};


// durationToClosure: Closure Time (end-to-end), closed minus earliest known start point, hours
if (dateTimeClosed == null) {
  durationToClosure = null;
} else {
  $start = null;

  // initialise with first non-null candidate
  $start = dateTimeEventOccurred ?? dateTimePaperRecorded ?? dateTimeKoboStarted ?? createdAt;

  if ($start == null) {
    durationToClosure = null;
  } else {
    // pick earliest among the candidates that exist
    if (dateTimePaperRecorded != null && datetime\diff(dateTimePaperRecorded, $start, 'seconds') < 0) { $start = dateTimePaperRecorded; }
    if (dateTimeKoboStarted  != null && datetime\diff(dateTimeKoboStarted,  $start, 'seconds') < 0) { $start = dateTimeKoboStarted; }
    if (createdAt            != null && datetime\diff(createdAt,            $start, 'seconds') < 0) { $start = createdAt; }
    if (dateTimeEventOccurred!= null && datetime\diff(dateTimeEventOccurred,$start, 'seconds') < 0) { $start = dateTimeEventOccurred; }

    durationToClosure = datetime\diff(dateTimeClosed, $start, 'minutes') / 60;
  }
};


// durationDigitalToClosure: hours from record creation in EspoCRM to closure
if (createdAt == null || dateTimeClosed == null) {
  durationDigitalToClosure = null;
} else {
  durationDigitalToClosure = datetime\diff(dateTimeClosed, createdAt, 'minutes') / 60;
};


// durationReportingDelayShare: proportion of total lifecycle time spent before reporting (fraction 0–1)
if (durationEventToReporting == null || durationToClosure == null || durationToClosure == 0) {
  durationReportingDelayShare = null;
} else {
  durationReportingDelayShare = durationEventToReporting / durationToClosure;
};


ifThen(
  assignedUserId != null && status == 'open',  // someone has been assigned or re-assigned and current status is 'Open'
  status = 'in_progress'                       // then set the status to 'In Progress'
);


